from ads_src import A
E=lambda *p:[("Subject",)+p[0],("Opener",)+p[1],("Format",)+p[2],("Offer",)+p[3],("Ask",)+p[4]]
A("ce-skyscraper","Brian Dean's Skyscraper outreach email","US","email","real_author","skyscraper",
 "Hey [Name], I was searching for some articles about [Your topic] today and I came across this page: [URL]. I noticed that you linked to one of my favorite articles – [Article title]. Just wanted to give you a heads up that I created a similar article. It's like [Name of the article], but more thorough and up to date: [URL]. Might be worth a mention on your page. Either way, keep up the awesome work! Cheers, [Your Name]",
 "good","Self-reported: 17 links from 160 emails (11%). Shows how he found them, offers something relevant, small ask, easy out. Caveat: he was already well known; Backlinko's own 12M-email study found ~8.5% of outreach emails get any reply.",
 E(("Not published.","—","Name their page or topic."),("'I was searching… and came across this page' — honest personalisation.","—","'Jag sökte på ”tandläkare Solna”…'"),("Short, plain.","—","—"),("A better resource.","'more thorough and up to date' is a claim.","Name ONE specific improvement."),("'Might be worth a mention' + easy out.","—","Small ask + 'either way'.")),metric="17/160 = 11% (self-reported).")
A("ce-harris","Bryan Harris: 'Demo' email selling a video series","US","email","real_author","woodpecker",
 "Subject: <CompanyName> Demo — I love <CompanyName> (been a customer for several months) and I'm also a big fan of your blog. I work with companies like KISSmetrics and make weekly video's for their blog. […] I made a demo for you based on a previous post […] Is this something you guys would be interested in?",
 "good","Reported: 4 of 6 opened, half of them watched the demo. The sample made for them IS the proof — exactly the free 'Google-kartan' report idea.",
 E(("Their company name + 'Demo'.","—","'Kartrapport för Solna Tandvård'."),("Real connection (customer, reader).","Slightly 'I'-heavy.","More 'you' than 'I'."),("Short paragraphs.","—","—"),("A demo made for them.","—","Do a small piece of the work first."),("Interest question.","—","—")),metric="4/6 opened, 2 watched (self-reported).")
A("ce-braun-hr","Josh Braun: 'Your Article in HR Magazine'","US","email","real_author","woodpecker",
 "Subject: Your Article in HR Magazine… Hey Beth, I noticed in a recent HR Magazine article that you folks are introducing 2 new health plans this year. […] we put together a free 4 part video series that might help you explain your plans in Plain English […] If you're interested, just reply and I'll send it along.",
 "good","A personal trigger (their article), a free useful resource and the smallest ask: 'just reply'. Teaching first, selling later.",
 E(("About them.","—","—"),("Specific observation from public info.","—","—"),("Plain, casual.","'super passionate' is filler.","Cut self-description."),("Free 4-part video series.","—","—"),("'just reply and I'll send it along'.","—","Model for your ask.")))
A("ce-wilcox","Justin Wilcox: customer-interview email","US","email","real_author","woodpecker",
 "Subject: Remote coding — Hi Sam, I read your article on volunteering your professional skills in Guatemala – it was really inspiring. […] I'm not looking to sell anything, but since you have so much expertise with remote coding, I'd love to get your advice […] If you're available, I'd love to chat for just 20 minutes – Thur or Fri morning?",
 "good","Reported ~50% success getting interviews. Short, personal, asks for advice (makes them the expert). For a cold SALES email, Gong found interest CTAs beat meeting asks — so borrow the opener, not the 20-minute ask.",
 E(("2 words, their topic.","—","—"),("Specific article + why it mattered.","—","—"),("5 sentences.","—","—"),("Their expertise valued.","—","—"),("20 min, two options.","Bigger ask than 'reply'.","For sales: ask interest first.")),metric="~50% (self-reported).")
A("ce-shoor","Iris Shoor: 'Server debugging in Scala at <CompanyName>'","US","email","real_author","woodpecker",
 "Subject: Server debugging in Scala at <CompanyName> — I'm a co-founder at Takipi, we're a startup developing a new technology to debug large scale production environments. […] I ran into some of your Play projects on Github and thought you might be a good contact point […]",
 "good","Reported 30–40% reply rate. Very specific subject, says where she found them and why them, names peer companies. Weak spot: opens with 'I'm a co-founder…'.",
 E(("Hyper-specific + company.","—","—"),("—","Starts with 'I'm'.","Start with where you found them."),("Longer.","—","Trim."),("Test drive.","—","—"),("Meet while visiting.","—","—")),metric="30–40% (self-reported).")
A("ce-daily","Dave Daily's email to Noah Kagan (cited by Noah)","US","email","real_author","woodpecker",
 "Subject: How I lost your Sperry's.. and apt. And why you should meet with me. — I kept bidding them up.. to $600. Then I stopped with 3 seconds left […] Why you should meet with me: 1. I'm the founder and CEO of Grav […] This Wednesday 4/17 at 10am (or earlier) would be a great time to come by […]",
 "bad","It worked for Noah (he met him) — but as a model for you emailing clinics it's risky: long, edgy humour including a profanity, and a specific meeting time from a stranger. Great story opener; don't copy the rest.",
 E(("Story + curiosity.","Very long.","Keep curiosity, cut length."),("A story with the reader in it.","—","—"),("Numbered reasons.","Long; contains profanity.","Never in a B2B email to clinics."),("App idea + factory visit.","—","—"),("Specific date & time.","Big ask from a stranger.","Small interest question first.")),note="Noah's own note: it would be better if it said how long the meeting would take.")
A("ce-reeder","Bernie Reeder: the '3 things' follow-up","US","email","real_author","woodpecker",
 "Hey <FirstName>, I haven't heard back from you and that tells me one of three things: 1) You've already chosen a different company for this […] 2) You're still interested but haven't had the time to get back to me yet. 3) You've fallen and can't get up […]",
 "good","Reported 46% reply rate on unresponsive prospects. A light joke + replying takes one digit + an easy no.",
 E(("Re: original subject (keeps the thread).","—","—"),("Honest: no reply yet.","—","—"),("Numbered options.","Humour can misfire.","Keep it kind in Swedish."),("—","—","—"),("Pick a number.","—","—")),metric="46% (self-reported).")
A("ce-braun-vm","Josh Braun: 'voicemail' follow-up with lettered answers","US","email","real_author","woodpecker",
 "Subject: voicemail — Hi Matt, First of all, happy day-before-a-long-weekend! […] simply hit 'reply,' and type the letter of the choice below that best fits the situation: A. OMG, this totally slipped off my priority list […] C. Unfortunately, this is off the table for the foreseeable future. Please quit bugging me about it.",
 "good","Reported 40% response rate. Friendly, replying takes one letter, and there's a polite 'no' option.",
 E(("One word, looks internal.","—","—"),("Human small talk.","Long-ish.","One line max."),("Lettered options.","—","—"),("—","—","—"),("Reply with a letter.","—","—")),metric="40% (self-reported).")
A("ce-morgan","Heather R. Morgan: '10x <Company>'s traction in 10 minutes'","US","email","real_author","woodpecker",
 "Subject: 10x <Company>'s traction in 10 minutes — I have an idea that I can explain in 10 minutes that can get <Company> its next 100 best customers. I recently used this idea to help our client <SaaSCompany> almost triple their monthly run rate. […] let's schedule a quick 10 minute call […]",
 "bad","Reported 57% open / 21% response — it worked for her. But '10x' and 'next 100 best customers' are big promises; without real case studies, copying this means making claims you can't prove. Good structure, risky claims.",
 E(("Number + their name.","'10x' is hype.","Use a checkable fact instead."),("Short.","Big promise.","—"),("3 sentences.","—","—"),("An idea.","Vague.","Offer something concrete (the report)."),("10-min call.","Meeting ask.","Interest question.")),metric="57% open, 21% response (self-reported).")
A("ce-shaw","Lena Shaw: '15 minutes to get <Company> more customers'","US","email","real_author","woodpecker",
 "Subject: 15 minutes to get <Company> more customers — Would you like to hear an idea for a 15 minute hack that could significantly increase <Company>'s conversion rate? Recently, <SaaS Company>, one of our B2B clients saw a 47% increase in signups after working with us. […]",
 "good","Reported 28% response. Short, a specific client result (47%) as proof, clear time cost. Only copy the proof part when you have a real result of your own.",
 E(("Time + outcome.","—","—"),("Question.","'hack' sounds salesy.","—"),("4 sentences.","—","—"),("Idea.","—","—"),("15-min call.","Meeting ask.","—")),metric="28% (self-reported).")
A("ce-mcgill","Justin McGill: 'Looking for an Accountant'","US","email","real_author","woodpecker",
 "Subject: Looking for an Accountant — I was wondering if you were looking for more business customers? I know the majority of small businesses are always looking for a great accountant […] Are there any types of businesses in particular that make good clients for you? P.S. If you aren't the right person to contact about this, please let me know.",
 "bad","Short and conversational, but the subject pretends to be a customer ('Looking for an Accountant') — a bait-and-switch that can burn trust. Keep the question ending, drop the trick subject.",
 E(("Looks like a lead.","Misleading.","Be honest about what it is."),("Question.","—","—"),("3 sentences + P.S.","—","—"),("Leads.","Vague.","—"),("Open question about their clients.","—","A good conversational ask.")))
A("ce-steli","Steli Efti: the referral email","US","email","real_author","woodpecker",
 "Hi <FirstName>, I hope I'm not bothering you. Could you please refer me to the person in charge of <Something that's relevant to my product>? Thanks for your time,",
 "good","Ultra-short referral ask — use it when you only have a general address. Weak spot: 'I hope I'm not bothering you' — apologising makes you sound small.",
 E(("'quick request' etc.","—","—"),("—","Apologises.","Drop the apology."),("2 sentences.","—","—"),("—","None.","Add why: 'jag har en gratis rapport om er Google-profil'."),("Who is the right person?","—","—")))
A("ce-kreuzberger","Bryan Kreuzberger: 'Appropriate person'","US","email","real_author","woodpecker",
 "Subject: Appropriate person — I am writing in hopes of finding the appropriate person who handles multicultural media? […] Each month we reach 25 million Spanish speakers […] If you are the appropriate person to speak with, what does your calendar look like? If not, who do you recommend I talk to?",
 "good","He reported ~80% response across 3 emails. A clear dual ask (you, or who?), concrete numbers, client names. The pitch in the middle is long — trim it.",
 E(("2 words, a small problem to solve.","—","—"),("Purpose immediately.","—","—"),("Long pitch paragraph.","Too long.","One sentence of proof."),("—","—","—"),("Calendar or referral.","—","—")),metric="~80% over 3 emails (self-reported).")
A("ce-sherer","John Sherer: value-add follow-up","US","email","real_author","woodpecker",
 "Subject: Re: <Subject Of Your Previous Email> — Hi Mark, Have you come across the 'Information Security Community?' Check the group out: <link>. From our last discussion this group looks to be filled with your target prospects […] What's the best way to get on your calendar for 15 tomorrow?",
 "good","A follow-up that GIVES something new (a resource) instead of 'just checking in'. That's the rule for your follow-ups: one new useful thing each time.",
 E(("Keeps the thread.","—","—"),("A useful resource.","—","—"),("Short.","—","—"),("A playbook.","—","—"),("15 min tomorrow.","Meeting ask.","Interest ask for cold.")))
A("ce-benson","Justin Benson: the apologetic first touch","US","email","real_author","woodpecker",
 "Hi John, Forgive me for the unsolicited email but it's better then me jamming up your VM. I'm not sure if we can help you but because we've helped <Two-Or-Three-Peer-Companies> I thought I'd check […] If any of these resonate with you I'm happy to discuss further via email or phone follow up – just let me know what you prefer.",
 "bad","Good: names peer companies and lists problems. Bad as a model for you: it opens by apologising ('Forgive me…', 'I'm not sure if we can help') — exactly the self-doubt you're training out. Lead with the observation instead.",
 E(("Problem-based options.","—","—"),("Apology.","Makes you small.","Start with their situation."),("Bullet list of problems.","—","Good."),("—","—","—"),("Email or phone.","Two options.","One easy yes.")))
A("ce-graham","Robert Graham: '30m interview to be featured on <BlogName>'","US","email","real_author","woodpecker",
 "Subject: 30m interview to be featured on <BlogName> — Hi Jack, I was bummed out when I noticed that you were also at Wildlife Expo '12. […] I run a blog that highlights exceptional breeders in Texas and I want to feature you guys. Would you be interested in a 30-minute interview via Skype or phone?",
 "good","Reported up to 50% response. Gives first (a feature), very personal, clear time cost.",
 E(("What they get + time.","—","—"),("Shared event.","—","—"),("Short.","—","—"),("Free exposure.","—","—"),("Interest question.","—","—")),metric="Up to 50% (self-reported).")
